function findPostBySlug(slug){
  for(var i=0;i<BLOG_POSTS.length;i++) if(BLOG_POSTS[i].slug===slug) return BLOG_POSTS[i];
  return null;
}

function parseHash(){
  var h = location.hash.replace(/^#\/?/, '');
  var parts = h.split('/').filter(Boolean);
  var lang = 'fr', page = 'accueil', post = null;
  if(parts[0] && SLUGS[parts[0]]) lang = parts[0];
  if(parts[1] && SLUG_MAP[parts[1]]) page = SLUG_MAP[parts[1]];
  if(page==='blog' && parts[2]) post = parts[2];
  return {lang:lang, page:page, post:post};
}

function setHash(page, lang){
  var slug = SLUGS[lang][page];
  location.hash = '#/' + lang + '/' + slug;
}

function goPost(slug){
  CP = 'blog'; CPOST = slug;
  location.hash = '#/' + CL + '/' + SLUGS[CL].blog + '/' + slug;
  render();
}

function go(page, lang){
  if(lang) CL = lang;
  if(page) CP = page;
  CPOST = null;
  setHash(CP, CL);
  render();
}

function render(){
  document.documentElement.lang = CL;
  document.getElementById('pg-title').textContent = T[CL].title;
  var md = document.getElementById('meta-desc');
  if(md) md.setAttribute('content', T[CL].desc);
  buildNav();
  buildPage();
  buildFooter();
  updateHreflang();
  window.scrollTo({top:0, behavior:'smooth'});
}

function updateHreflang(){
  var existing = document.querySelectorAll('link[rel="alternate"]');
  for(var i=0;i<existing.length;i++) existing[i].remove();
  var langs = ['fr','en','es'];
  for(var i=0;i<langs.length;i++){
    var l = document.createElement('link');
    l.rel = 'alternate'; l.hreflang = langs[i];
    l.href = location.origin + location.pathname + '#/' + langs[i] + '/' + SLUGS[langs[i]][CP];
    document.head.appendChild(l);
  }
}

function buildNav(){
  var t = T[CL];
  var nl = document.getElementById('nav-menu');
  var h = '';
  for(var i=0;i<PAGES.length;i++){
    var p = PAGES[i];
    h += '<li><a class="' + (CP===p?'act':'') + '" href="#/' + CL + '/' + SLUGS[CL][p] + '" data-pg="' + p + '">' + t.nav[i] + '</a></li>';
  }
  h += '<li><div class="nav-lang">';
  var langs=['fr','en','es'], flags=['FR','EN','ES'];
  for(var j=0;j<3;j++){
    h += '<button class="' + (CL===langs[j]?'on':'') + '" data-lg="' + langs[j] + '">' + flags[j] + '</button>';
  }
  h += '</div></li>';
  nl.innerHTML = h;
}

function buildFooter(){
  var t = T[CL];
  document.getElementById('ft-slogan').textContent = t.slogan;
  var fn = '';
  for(var i=0;i<PAGES.length;i++){
    fn += '<a href="#/' + CL + '/' + SLUGS[CL][PAGES[i]] + '" data-pg="' + PAGES[i] + '">' + t.nav[i] + '</a>';
  }
  document.getElementById('ft-nav').innerHTML = fn;
  document.getElementById('ft-affil').textContent = t.ft_affil;
  document.getElementById('ft-legal').textContent = t.ft_legal;
  document.getElementById('ft-copy').textContent = t.ft_copy;
  document.getElementById('ft-desc').textContent = t.ft_desc;
}

function buildPage(){
  for(var i=0;i<PAGES.length;i++){
    var el = document.getElementById('pg-' + PAGES[i]);
    el.style.display = 'none';
    el.innerHTML = '';
  }
  var el = document.getElementById('pg-' + CP);
  el.style.display = 'block';
  if(CP==='blog' && CPOST){
    var post = findPostBySlug(CPOST);
    if(post && CL==='fr') buildBlogPost(el, post);
    else buildBlog(el);
  }
  else if(CP==='accueil') buildAccueil(el);
  else if(CP==='apropos') buildApropos(el);
  else if(CP==='produits') buildProduits(el);
  else if(CP==='blog') buildBlog(el);
  else if(CP==='contact') buildContact(el);
}

/* Event delegation - single listener handles all nav clicks + lang switches */
document.addEventListener('click', function(e){
  var pgEl = e.target.closest('[data-pg]');
  if(pgEl){
    e.preventDefault();
    go(pgEl.getAttribute('data-pg'), null);
    return;
  }
  var postEl = e.target.closest('[data-post]');
  if(postEl){
    e.preventDefault();
    goPost(postEl.getAttribute('data-post'));
    return;
  }
  var lgEl = e.target.closest('[data-lg]');
  if(lgEl){
    e.preventDefault();
    go(null, lgEl.getAttribute('data-lg'));
    return;
  }
});

window.addEventListener('hashchange', function(){
  var r = parseHash();
  CL = r.lang; CP = r.page; CPOST = r.post;
  render();
});
